import React, { useState, useEffect } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { BarChart3, PawPrint, Milk, ShieldCheck } from 'lucide-react';
import toast from 'react-hot-toast';

function Modal({ isOpen, onClose, title, content }) {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/50" onClick={onClose} />
      <div className="relative rounded-2xl shadow-2xl w-full max-w-2xl max-h-[80vh] overflow-auto p-6 bg-white dark:bg-slate-900 text-slate-800 dark:text-slate-100">
        <button onClick={onClose} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600">
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
        <h2 className="text-2xl font-bold mb-4">{title}</h2>
        <div className="prose max-w-none text-slate-600 dark:text-slate-300 text-sm leading-relaxed">{content}</div>
      </div>
    </div>
  );
}

export default function LoginPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [modalTitle, setModalTitle] = useState('');
  const [modalContent, setModalContent] = useState('');

  const { login, loginDemo, user, isAuthenticated } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    if (isAuthenticated && user) {
      const target = location.state?.from?.pathname || '/dashboard';
      navigate(target, { replace: true });
    }
  }, [isAuthenticated, user, navigate, location]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    const cleanEmail = email.trim();
    if (!cleanEmail || !password) {
      toast.error('Lütfen e-posta ve şifrenizi girin.');
      return;
    }

    setLoading(true);
    try {
      await login(cleanEmail, password, rememberMe);
      toast.success('Giriş başarılı! Yönlendiriliyorsunuz...');
      const target = location.state?.from?.pathname || '/dashboard';
      setTimeout(() => {
        navigate(target, { replace: true });
      }, 150);
    } catch (err) {
      console.error('Login error:', err);
      let errorMessage = 'Giriş yapılamadı.';
      if (err.response?.data?.error) {
        errorMessage = err.response.data.error;
      } else if (err.response?.data?.message) {
        errorMessage = err.response.data.message;
      } else if (err.message) {
        errorMessage = err.message;
      }
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  const handleDemoLogin = async () => {
    setLoading(true);
    try {
      await loginDemo();
      toast.success('Demo hesabı ile giriş yapıldı!');
      navigate('/dashboard', { replace: true });
    } catch (err) {
      console.error('Demo login error:', err);
      toast.error(err.response?.data?.error || 'Demo girişi şu an kullanılamıyor.');
    } finally {
      setLoading(false);
    }
  };

  const openModal = (type) => {
    if (type === 'privacy') {
      setModalTitle('Gizlilik Politikası');
      setModalContent(
        <div className="space-y-4">
          <p>mFk Farm kullanıcılarının kişisel ve çiftlik verilerinin gizliliği 6698 sayılı KVKK kapsamında korunmaktadır. Verileriniz şifrelenmiş sunucularda güvenle saklanır ve üçüncü şahıslarla paylaşılmaz.</p>
        </div>
      );
    } else if (type === 'terms') {
      setModalTitle('Hizmet Koşulları');
      setModalContent(
        <div className="space-y-4">
          <p>mFk Farm platformunu kullanarak sisteme kaydedilen tüm operasyonel verilerin doğruluğu ve hesap güvenliği kullanıcı sorumluluğundadır.</p>
        </div>
      );
    }
    setModalOpen(true);
  };

  const featureCards = [
    { 
      icon: BarChart3, 
      title: 'Akıllı Analiz', 
      desc: 'Verilerinizi anlık raporlara dönüştürün',
      badgeClass: 'bg-emerald-500/20 border-emerald-400/30 text-emerald-300'
    },
    { 
      icon: PawPrint, 
      title: 'Hayvan Takibi', 
      desc: 'Sağlık, aşı ve soy ağacı kayıtları',
      badgeClass: 'bg-teal-500/20 border-teal-400/30 text-teal-300'
    },
    { 
      icon: Milk, 
      title: 'Süt Verimi', 
      desc: 'Günlük ve aylık sağım optimizasyonu',
      badgeClass: 'bg-cyan-500/20 border-cyan-400/30 text-cyan-300'
    },
    { 
      icon: ShieldCheck, 
      title: 'Tam Güvenlik', 
      desc: 'Endüstri standardı şifreleme ve yedekleme',
      badgeClass: 'bg-emerald-500/20 border-emerald-400/30 text-emerald-300'
    },
  ];

  return (
    <div className="h-screen w-screen overflow-hidden flex flex-col md:flex-row bg-slate-900">
      <Modal isOpen={modalOpen} onClose={() => setModalOpen(false)} title={modalTitle} content={modalContent} />

      {/* Sol Panel - Görsel & Bilgi (Tek ekrana tam sığacak şekilde) */}
      <div className="hidden md:flex md:w-[65%] lg:w-[70%] xl:w-[72%] bg-slate-900 relative overflow-hidden h-full flex-col justify-between items-center px-8 lg:px-14 py-6 text-white text-center">
        <div className="absolute inset-0">
          <div className="absolute top-1/4 right-1/4 w-96 h-96 bg-gradient-to-br from-emerald-500 to-teal-600 rounded-full blur-3xl opacity-35 pointer-events-none" />
          <div className="absolute bottom-1/4 left-1/4 w-80 h-80 bg-gradient-to-tr from-teal-500 to-green-400 rounded-full blur-3xl opacity-25 pointer-events-none" />
        </div>

        <div className="my-auto flex flex-col items-center w-full max-w-2xl px-2 relative z-10">
          {/* Logo Büyütüldü & Yazılar Sağına Geldi */}
          <div className="flex items-center justify-center gap-6 lg:gap-8 mb-6 lg:mb-7 w-full text-left">
            <img 
              src="/mfk-logo.png?v=7" 
              alt="mFk Farm" 
              className="w-44 h-44 md:w-56 md:h-56 lg:w-64 lg:h-64 object-contain drop-shadow-2xl hover:scale-105 transition-all duration-300 flex-shrink-0" 
            />
            <div className="flex flex-col justify-center">
              <h1 className="text-4xl md:text-5xl lg:text-6xl font-black tracking-tight text-white drop-shadow-md">mFk Farm</h1>
              <p className="text-emerald-400 text-lg md:text-xl lg:text-2xl font-bold mt-1 tracking-wide">Akıllı Çiftlik Yönetim Sistemi</p>
              <p className="text-sm md:text-base font-normal leading-relaxed text-slate-300 mt-2 max-w-md">
                Tüm çiftliğinizi tek bir platformdan, her cihazdan güvenle yönetin.
              </p>
            </div>
          </div>

          {/* 4 Kart: Ortalanmış Yazılar ve Profesyonel İkonlar */}
          <div className="grid grid-cols-2 gap-3.5 lg:gap-4 w-full">
            {featureCards.map((item, i) => {
              const IconComp = item.icon;
              return (
                <div 
                  key={i} 
                  className="group bg-white/[0.08] hover:bg-white/[0.13] backdrop-blur-md rounded-2xl p-4 lg:p-5 border border-white/10 hover:border-emerald-400/50 transition-all duration-300 shadow-xl flex flex-col items-center justify-center text-center"
                >
                  <div className={`w-12 h-12 rounded-xl flex items-center justify-center mb-2.5 ${item.badgeClass} border shadow-lg group-hover:scale-110 transition-transform duration-300`}>
                    <IconComp className="w-6 h-6 stroke-[2.2]" />
                  </div>
                  <h3 className="font-bold text-sm md:text-base text-white text-center group-hover:text-emerald-300 transition-colors">
                    {item.title}
                  </h3>
                  <p className="text-xs text-slate-300 mt-1 text-center leading-relaxed">
                    {item.desc}
                  </p>
                </div>
              );
            })}
          </div>
        </div>

        <div className="w-full text-center pt-2 relative z-10">
          <p className="text-xs text-slate-400">
            © 2026 mFk Games •{' '}
            <button onClick={() => openModal('privacy')} className="hover:text-emerald-400 transition-colors">Gizlilik (Privacy)</button>{' '}
            •{' '}
            <button onClick={() => openModal('terms')} className="hover:text-emerald-400 transition-colors">Hizmet Koşulları (Terms)</button>
          </p>
          <p className="text-[11px] text-slate-400/90 mt-1 font-medium tracking-wide">
            All rights reserved. Unauthorized copying, distribution or reproduction is strictly prohibited.
          </p>
        </div>
      </div>

      {/* Sağ Panel - Giriş Formu (Tek ekrana tam sığacak şekilde) */}
      <div className="w-full md:w-[35%] lg:w-[30%] xl:w-[28%] flex items-center justify-center p-6 lg:p-8 bg-slate-50 dark:bg-slate-900 h-full overflow-y-auto">
        <div className="w-full max-w-[340px]">
          {/* Mobil Görünüm İçin Logo */}
          <div className="md:hidden text-center mb-6">
            <img src="/mfk-logo.png" alt="mFk Farm" className="w-20 h-20 object-contain mx-auto mb-2" />
            <h2 className="text-2xl font-black text-slate-900 dark:text-white">mFk Farm</h2>
            <p className="text-xs text-emerald-600 font-bold">Akıllı Çiftlik Yönetim Sistemi</p>
          </div>

          <div className="mb-6 text-left">
            <h2 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight">Giriş Yap</h2>
            <p className="text-slate-500 dark:text-slate-400 text-sm mt-1 font-medium">Hesabınıza erişmek için bilgilerinizi girin</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider mb-1.5">
                E-POSTA
              </label>
              <input
                type="email"
                required
                autoComplete="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="ornek@ciftlik.com"
                className="w-full px-3.5 py-2.5 text-sm rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-emerald-500 focus:border-transparent transition-all"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider mb-1.5">
                ŞİFRE
              </label>
              <div className="relative">
                <input
                  type={showPassword ? 'text' : 'password'}
                  required
                  autoComplete="current-password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="••••••••"
                  className="w-full px-3.5 py-2.5 pr-10 text-sm rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-emerald-500 focus:border-transparent transition-all"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                >
                  {showPassword ? (
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029c.654-.616 1.489-1.336 2.294-2.058M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M6 9a9 9 0 000-18 9 9 0 0018 9z"/></svg>
                  ) : (
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>
                  )}
                </button>
              </div>
            </div>

            <div className="flex items-center justify-between pt-1">
              <label className="flex items-center cursor-pointer">
                <input
                  type="checkbox"
                  checked={rememberMe}
                  onChange={(e) => setRememberMe(e.target.checked)}
                  className="w-4 h-4 text-emerald-600 border-slate-300 rounded focus:ring-emerald-500"
                />
                <span className="ml-2 text-xs font-medium text-slate-600 dark:text-slate-400">Beni hatırla</span>
              </label>

              <Link
                to="/forgot-password"
                className="text-xs font-bold text-emerald-600 hover:text-emerald-700 transition-colors"
              >
                Şifremi unuttum?
              </Link>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full py-3 bg-emerald-600 hover:bg-emerald-700 text-white text-sm font-bold rounded-xl shadow-lg shadow-emerald-600/25 transition-all disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center gap-2"
            >
              {loading ? (
                <>
                  <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                  Giriş Yapılıyor...
                </>
              ) : (
                'Giriş Yap'
              )}
            </button>

            <button
              type="button"
              onClick={handleDemoLogin}
              disabled={loading}
              className="w-full py-2.5 bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 text-xs font-bold rounded-xl transition-colors"
            >
              Demo Çiftlik İle Dene
            </button>
          </form>

          <div className="mt-8 text-center">
            <p className="text-xs text-slate-500 dark:text-slate-400 font-medium">
              Hesabınız yok mu?{' '}
              <Link to="/register" className="text-emerald-600 font-bold hover:underline">
                Ücretsiz Kaydol
              </Link>
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
